CREATE FUNCTION public.company_daily_results() RETURNS TABLE(day date,revenue numeric,expenses numeric,net numeric,cash_flow numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH owner AS(SELECT id FROM companies WHERE user_id=auth.uid()), days AS(SELECT generate_series((current_date-29)::timestamp,current_date::timestamp,interval '1 day')::date AS day), ledger AS(SELECT (created_at AT TIME ZONE 'UTC')::date AS day,coalesce(sum(amount) FILTER(WHERE entry_type='TICKET_REVENUE'),0) AS revenue,coalesce(sum(amount) FILTER(WHERE entry_type IN ('FUEL_EXPENSE','AIRPORT_FEES','HANDLING_FEES','MAINTENANCE_RESERVE')),0) AS expenses,sum(company_delta) AS cash FROM company_ledger WHERE company_id IN(SELECT id FROM owner) AND created_at>=current_date-29 GROUP BY 1), leases AS(SELECT d.day,coalesce(sum(k.weekly_rate/7*greatest(0,extract(epoch FROM least(k.ends_at,now(),(d.day+1)::timestamptz)-greatest(k.starts_at,d.day::timestamptz))/86400)),0) AS cost FROM days d LEFT JOIN lease_contracts k ON k.company_id IN(SELECT id FROM owner) AND k.starts_at<(d.day+1)::timestamptz AND k.ends_at>d.day::timestamptz GROUP BY d.day) SELECT d.day,coalesce(l.revenue,0),coalesce(l.expenses,0)+k.cost,coalesce(l.revenue,0)-coalesce(l.expenses,0)-k.cost,coalesce(l.cash,0) FROM days d LEFT JOIN ledger l USING(day) JOIN leases k USING(day) WHERE EXISTS(SELECT 1 FROM owner) ORDER BY d.day $$; REVOKE ALL ON FUNCTION public.company_daily_results() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.company_daily_results() TO authenticated;
CREATE OR REPLACE FUNCTION public.start_test_flight(p_flight uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f flights%ROWTYPE; cid uuid; BEGIN SELECT id INTO cid FROM companies WHERE user_id=auth.uid() FOR UPDATE; SELECT * INTO f FROM flights WHERE id=p_flight AND company_id=cid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Flight not found'; END IF; IF f.execution_source<>'WEB_MANUAL' OR NOT coalesce((SELECT (value #>> '{}')::boolean FROM economy_config WHERE key='web_simulation_enabled'),false) THEN RAISE EXCEPTION 'Test simulation disabled'; END IF; IF f.status='EN_ROUTE' THEN RETURN; END IF; IF f.status<>'DISPATCHED' THEN RAISE EXCEPTION 'Invalid flight state'; END IF; UPDATE flights SET status='EN_ROUTE',departed_at=now(),rules_snapshot=jsonb_set(rules_snapshot,'{simulation_time_scale}',to_jsonb(greatest(1,economy_number('simulation_time_scale')))) WHERE id=f.id; UPDATE fleet_aircraft SET status='EN_ROUTE' WHERE id=f.aircraft_id; END $$;
CREATE FUNCTION public.settle_due_test_flights() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f record; BEGIN IF NOT coalesce((SELECT (value #>> '{}')::boolean FROM economy_config WHERE key='web_simulation_enabled'),false) THEN RETURN; END IF; PERFORM 1 FROM companies WHERE user_id=auth.uid() FOR UPDATE; FOR f IN SELECT id FROM flights WHERE company_id IN(SELECT id FROM companies WHERE user_id=auth.uid()) AND execution_source='WEB_MANUAL' AND status='EN_ROUTE' AND now()>=departed_at+make_interval(secs=>((estimated_minutes*60)/greatest(1,(rules_snapshot->>'simulation_time_scale')::numeric))::double precision) ORDER BY created_at LOOP PERFORM settle_flight(f.id); END LOOP; END $$; REVOKE ALL ON FUNCTION public.settle_due_test_flights() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.settle_due_test_flights() TO authenticated;